def separate_paren_groups(paren_string: str) -> List[str]:
    stack = []
    result = []
    i = 0
    n = len(paren_string)

    while i < n:
        if paren_string[i] == '(':
            stack.append(i)
            i += 1
        elif stack:
            open_idx = stack.pop()
            result.append(paren_string[open_idx + 1:i])
            i += 1
        else:
            i += 1

    return result
